import{_ as s,l,o as a,c as i,v as o,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"自旋锁","description":"","frontmatter":{"title":"自旋锁","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/spinlock.md","filePath":"cs/spinlock.md","lastUpdated":1789023840000}'),_={name:"cs/spinlock.md"};function h(m,e,u,f,E,S){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="自旋锁" tabindex="-1">自旋锁 <a class="header-anchor" href="#自旋锁" aria-label="Permalink to &quot;自旋锁&quot;">​</a></h1><div class="epigraph"><p>自旋锁在拿不到时原地忙等；持有期间不能睡眠，临界区必须短，否则它把 CPU 烧成等待器。</p><footer>—— 据 Love, Linux Kernel Development；Tanenbaum MOS 整理</footer></div><p><a href="/cs/lock-irq">上一课</a>给出互斥要用原子能力，并分清：IRQ 上下文只能忙等，同核还要关中断。缺口是把 <strong>spinlock</strong> 收成对象：锁字 + 获取时循环 RMW + 释放时写 0 并带 release 语义。本课钉何时能用、为何不能睡，不把 MCS 队列锁写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>睡眠锁在拿不到时<a href="/cs/context-switch">上下文切换</a>，但 ISR 与软中断不能调度。共享「线程与硬 IRQ」的队列必须自旋。单核上若不关 IRQ，持锁线程被同核 ISR 抢到同一把锁会自死等。多核上关本地 IRQ 挡不住他核，仍要自旋。缺口不是再讲 RMW 指令，而是这把<strong>短临界区锁</strong>的纪律。</p><p><span class="marginnote">持自旋锁时开抢占会让持有者被迁走，等待者在别的核上空转。因此获取路径关抢占；释放时再开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>spin_lock</code>：关抢占，必要时关本地 IRQ（<code>spin_lock_irqsave</code>），然后 <code>while (test_and_set)</code>；有的实现先读后 TAS 以减轻乒乓。<code>spin_unlock</code>：store-release 清锁，恢复 IRQ 与抢占。临界区只碰已经在内存里的结构，不调可能睡眠的分配、不 <code>copy_from_user</code>。</p>',8)),(a(),n(p,null,{default:t(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACQ%5B%22%E5%85%B3%E6%8A%A2%E5%8D%A0%E5%B9%B6%20TAS%20%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20CS%5B%22%E6%9E%81%E7%9F%AD%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%0A%20%20CS%20--%3E%20REL%5B%22release%20%E6%B8%85%E9%94%81%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>调试用的锁依赖检测记住获取顺序，那是死锁课；本课只要求一把锁的正确用法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自旋把等待变成 CPU 时间，换来不睡眠、可在 IRQ 用。临界区一长，<a href="/cs/scheduling-metrics">调度指标</a> 的响应与实时 WCET 一起坏掉，也会加重反转：高优先级在自旋，低优先级持锁却跑不完。PI 对纯自旋支持差，因为等待者不睡，调度器看不见。</p><p>简单 TAS 锁所有等待者打同一 cache 行；核多时要排队锁，下一课 MCS。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>raw_spinlock</code> 与 RT 里改睡眠的路径写完。用户态自旋在锁持有者被切走时会空转整个量子，一般要 futex。也不把读写锁提前展开。</p><p>后课默认：IRQ 与极短内核路径用自旋。多核排队减少乒乓，下一课 MCS 锁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自旋：忙等、禁睡、关抢占；与 IRQ 共享数据时还要关本地中断。</li><li>临界区必须短；简单 TAS 会乒乓。</li><li>排队自旋是下一课。</li><li>出处：Love, <em>LKD</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const k=s(_,[["render",h]]);export{A as __pageData,k as default};
